package com.yeyamo_mobile.api.notification_service.infrastructure.messaging;
import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;
class EventNotificationPolicyTest{private final ObjectMapper mapper=new ObjectMapper();private final EventNotificationPolicy policy=new EventNotificationPolicy(mapper);@Test void mapsUserCreatedRecipientAndEmail()throws Exception{UUID id=UUID.randomUUID();var result=policy.map(mapper.readTree("{\"eventId\":\""+id+"\",\"eventType\":\"user.created\",\"eventVersion\":1,\"payload\":{\"userId\":\"42\",\"email\":\"u@test.io\"}}"));assertEquals(1,result.size());assertEquals("42",result.getFirst().recipientId());assertEquals("u@test.io",result.getFirst().email());}@Test void mapsPartnerDecisionToOwner()throws Exception{var result=policy.map(mapper.readTree("{\"eventId\":\""+UUID.randomUUID()+"\",\"eventType\":\"partner.approved\",\"eventVersion\":1,\"payload\":{\"ownerUserId\":\"7\",\"legalName\":\"Travel Co\"}}"));assertEquals("7",result.getFirst().recipientId());}@Test void ignoresEventsWithoutNotificationRule()throws Exception{assertTrue(policy.map(mapper.readTree("{\"eventId\":\""+UUID.randomUUID()+"\",\"eventType\":\"content.post.updated\",\"eventVersion\":1,\"payload\":{}}")).isEmpty());}@Test void rejectsUnsupportedVersion()throws Exception{var event=mapper.readTree("{\"eventId\":\""+UUID.randomUUID()+"\",\"eventType\":\"user.created\",\"eventVersion\":2,\"payload\":{\"userId\":\"1\"}}");assertThrows(IllegalArgumentException.class,()->policy.map(event));}}
